123	void esched_query_sync_msg_trace(uint32_t dev_id, struct event_summary *event, uint32_t grp_id, uint32_t thread_id)
124	{
125	    drvError_t ret;
126	    struct sched_ioctl_para_trace para;
127	
128	    if ((dev_id >= ESCHED_DEV_NUM) || (grp_id < SCHED_MAX_DEFAULT_GRP_NUM)) {
129	        sched_err("input param is invalid. (dev_id=%u; grp_id=%u; thread_id=%u)\n", dev_id, grp_id, thread_id);
130	        return;
131	    }
132	
133	    para.input.dev_id = (unsigned int)dev_id;
134	    para.input.dst_pid = (unsigned int)event->pid;
135	    para.input.dst_gid = event->grp_id;
136	    para.input.dst_engine = event->dst_engine;
137	    para.input.event_id = event->event_id;
138	    para.input.subevent_id = event->subevent_id;
139	    para.input.msg = *((struct sync_msg_info *)event->msg);
140	    ret = esched_dev_ioctl(dev_id, SCHED_QUERY_SYNC_MSG_TRACE, &para);
141	    if (ret != DRV_ERROR_NONE) {
142	        sched_err("query trace fail. (ret=%d; dev_id=%u; grp_id=%u; thread_id=%u)\n", ret, dev_id, grp_id, thread_id);
143	        return;
144	    }
145	
146	    sched_run_info("trace event cfg. (dev_id=%u; grp_id=%u; thread_id=%u; event_id=%u; subevent_id=%u; pid=%d; dst_engine=%d).\n",
147	        dev_id, grp_id, thread_id, event->event_id, event->subevent_id, event->pid, event->dst_engine);
148	    sched_run_info("show trace info. (src_submit_user=%llu; src_submit_kernel=%llu; dst_publish=%llu; dst_wait_start=%llu; dst_wait_end=%llu;"
149	        " dst_submit_usr=%llu; dst_rsp_submit_kernel=%llu; src_publish=%llu; src_wait_start=%llu; src_wait_end=%llu).\n",
150	        para.trace.src_submit_user_timestamp, para.trace.src_submit_kernel_timestamp, para.trace.dst_publish_timestamp,
151	        para.trace.dst_wait_start_timestamp, para.trace.dst_wait_end_timestamp, para.trace.dst_submit_user_timestamp,
152	        para.trace.dst_submit_kernel_timestamp, para.trace.src_publish_timestamp, para.trace.src_wait_start_timestamp,
153	        para.trace.src_wait_end_timestamp);
154	
155	    return;
156	}
