241	static void esched_create_thread_wait_info_list_head(void)
242	{
243	    esched_thread_wait_info_head *wait_info_head = NULL;
244	    int ret;
245	
246	    if (esched_thread_key_flag == false) {
247	        sched_err("No esched_thread_key was created!\n");
248	        return;
249	    }
250	
251	    wait_info_head = (esched_thread_wait_info_head *)malloc(sizeof(esched_thread_wait_info_head));
252	    if (wait_info_head == NULL) {
253	        sched_err("malloc list_head failed.\n");
254	        return;
255	    }
256	
257	    INIT_LIST_HEAD(&wait_info_head->list_head);
258	    wait_info_head->cur_thread_info.gid = SCHED_INVALID_GID;
259	    wait_info_head->cur_thread_info.tid = SCHED_INVALID_TID;
260	    ret = pthread_setspecific(esched_thread_key, (void*)wait_info_head);
261	    if (ret != 0) {
262	        sched_err("set esched_thread_key specific failed.\n");
263	        free(wait_info_head);
264	        return;
265	    }
266	}
267	
268	static void esched_thread_destructor(void *key)
269	{
270	    esched_thread_wait_info_head *wait_info_head = NULL;
271	    struct list_head *pos = NULL, *n = NULL;
272	    esched_thread_wait_info *thread_wait_info = NULL;
273	
274	    wait_info_head = (esched_thread_wait_info_head *)key;
275	    if (wait_info_head == NULL) {
276	        return;
277	    }
278	
279	    list_for_each_safe(pos, n, &wait_info_head->list_head) {
280	        thread_wait_info = list_entry(pos, esched_thread_wait_info, list);
281	        drv_user_list_del(&thread_wait_info->list);
282	        sched_debug("Free thread wait info node(dev_id=%u; gid=%u; tid=%u).\n",
283	            thread_wait_info->thread_info.dev_id, thread_wait_info->thread_info.gid,
284	            thread_wait_info->thread_info.tid);
285	        free(thread_wait_info);
286	    }
287	
288	    free(wait_info_head);
289	}
290	
291	static void esched_create_thread_key_once(void)
292	{
293	    int ret;
294	
295	    ret = pthread_key_create(&esched_thread_key, esched_thread_destructor);
296	    if (ret != 0) {
297	        sched_err("pthread_key_create failed. (ret=%d)\n", ret);
