304	/* Findout the same "devid + grpid + thread_id" list entry. */
305	STATIC esched_thread_wait_info* esched_find_wait_info(unsigned int dev_id, unsigned int grp_id, unsigned int thread_id)
306	{
307	    esched_thread_wait_info_head *wait_info_head = NULL;
308	    struct list_head *pos = NULL, *n = NULL;
309	    esched_thread_wait_info *thread_wait_info = NULL;
310	
311	    wait_info_head = esched_get_thread_wait_info_list_head();
312	    if (wait_info_head == NULL) {
313	        return NULL;
314	    }
315	
316	    list_for_each_safe(pos, n, &wait_info_head->list_head) {
317	        thread_wait_info = list_entry(pos, esched_thread_wait_info, list);
318	        if (esched_thread_info_is_match(&thread_wait_info->thread_info, dev_id, grp_id, thread_id) == true) {
319	            return thread_wait_info;
320	        }
321	    }
322	
323	    return NULL;
324	}
325	
326	STATIC esched_thread_wait_info* esched_create_wait_info(unsigned int dev_id, unsigned int grp_id, unsigned int thread_id)
327	{
328	    esched_thread_wait_info_head *wait_info_head = NULL;
329	    esched_thread_wait_info *thread_wait_info = NULL;
330	
331	    wait_info_head = esched_get_thread_wait_info_list_head();
332	    if (wait_info_head == NULL) {
333	        sched_err("No wait info list.\n");
334	        return NULL;
335	    }
336	
337	    thread_wait_info = (esched_thread_wait_info *)malloc(sizeof(esched_thread_wait_info));
338	    if (thread_wait_info == NULL) {
339	        sched_err("malloc esched_thread_wait_info failed.\n");
340	        return NULL;
341	    }
342	
343	    esched_save_thread_info(thread_wait_info, dev_id, grp_id, thread_id);
344	    drv_user_list_add_head(&thread_wait_info->list, &wait_info_head->list_head);
345	    sched_debug("Add thread wait info node(dev_id=%u; gid=%u; tid=%u).\n",
346	        dev_id, grp_id, thread_id);
347	    return thread_wait_info;
348	}
