350	/* Findout and call the same "devid + grpid + thread_id" finish func. */
351	STATIC void esched_finish_call_back(unsigned int dev_id, unsigned int grp_id, unsigned int thread_id)
352	{
353	    esched_thread_wait_info *thread_wait_info;
354	
355	    thread_wait_info = esched_find_wait_info(dev_id, grp_id, thread_id);
356	    if (thread_wait_info == NULL) {
357	        return; /* It's probably no wait before. */
358	    }
359	
360	    if (thread_wait_info->event_valid == 0) {
361	        return; /* No need to call finish func. */
362	    }
363	
364	    /* Only valid parameters are saved in the wait info, so the gid and event_id found in the list must be valid. */
365	    if (esched_finish_func[grp_id][thread_wait_info->event_info.event_id] != NULL) {
366	        esched_finish_func[grp_id][thread_wait_info->event_info.event_id](dev_id,
367	            grp_id, thread_wait_info->event_info.event_id, thread_wait_info->event_info.subevent_id);
368	    }
369	    if (esched_finish_func_ex[grp_id][thread_wait_info->event_info.event_id] != NULL) {
370	        esched_finish_func_ex[grp_id][thread_wait_info->event_info.event_id](dev_id,
371	            grp_id, thread_wait_info->event_info);
372	    }
373	
374	    /* Update the last event info invalid. */
375	    thread_wait_info->event_valid = 0;
376	
377	    sched_debug("Called the finish func.(dev_id=%u; gid=%u; tid=%u; event_id=%u; subevent_id=%u).\n", dev_id, grp_id,
378	        thread_id, thread_wait_info->event_info.event_id, thread_wait_info->event_info.subevent_id);
379	}
380	
381	static void esched_save_wait_info(uint32_t dev_id, uint32_t thread_id, struct sched_ioctl_para_wait para)
382	{
383	    esched_thread_wait_info *thread_wait_info = NULL;
384	
385	    esched_update_cur_thread_info(para.event.gid, thread_id);
386	
387	    thread_wait_info = esched_find_wait_info(dev_id, para.event.gid, thread_id);
388	    if (thread_wait_info == NULL) {
389	        /* Create new wait info when first time wait by this thread info. */
390	        thread_wait_info = esched_create_wait_info(dev_id, para.event.gid, thread_id);
391	        if (thread_wait_info == NULL) {
392	            sched_err("Create new wait info failed. (dev_id=%u; grp_id=%u; tid=%u)\n", dev_id, para.event.gid, thread_id);
393	            return;
394	        }
395	    }
396	
397	    thread_wait_info->event_info.event_id = para.event.event_id;
398	    thread_wait_info->event_info.subevent_id = para.event.subevent_id;
399	    thread_wait_info->event_info.msg_len = para.event.msg_len;
400	    (void)memcpy_s(thread_wait_info->event_info.msg, EVENT_MAX_MSG_LEN, para.input.msg, para.event.msg_len);
401	    thread_wait_info->event_valid = 1;
402	}
