520	STATIC int32_t esched_dev_init(unsigned int dev_id)
521	{
522	    int32_t ret = 0;
523	    int fd;
524	
525	    if (esched_device_check(dev_id) != 0) {
526	        sched_err("The dev_id is invalid. (dev_id=%u; max=%u)\n", dev_id, ESCHED_LOGIC_DEV_NUM);
527	        return DRV_ERROR_INVALID_DEVICE;
528	    }
529	
530	    (void)pthread_mutex_lock(&g_esched_init_mutex);
531	    if (sched_dev_fd[dev_id] == SCHED_DEV_FD_CLOSED) {
532	        (void)pthread_mutex_unlock(&g_esched_init_mutex);
533	        return DRV_ERROR_SCHED_PROCESS_EXIT;
534	    }
535	
536	    if (sched_dev_fd[dev_id] > 0) {
537	        (void)pthread_mutex_unlock(&g_esched_init_mutex);
538	        return 0;
539	    }
540	
541	    fd = esched_open(SCHED_CHAR_DEV_FULL_NAME);
542	    if (fd < 0) {
543	        sched_err("Failed to open device. (ret=%d)\n", errno);
544	        (void)pthread_mutex_unlock(&g_esched_init_mutex);
545	        return DRV_ERROR_INVALID_DEVICE;
546	    }
547	
548	#ifdef CFG_FEATURE_EXTERNAL_CDEV
549	    ret = esched_ex_dev_open(dev_id, fd);
550	    if (ret != 0) {
551	        (void)pthread_mutex_unlock(&g_esched_init_mutex);
552	        esched_close(fd);
553	        return ret;
554	    }
555	#endif
556	
557	    ret = esched_init_sched_cpu_num(dev_id, fd);
558	    if (ret != 0) {
559	        sched_err("Failed to init sched cpu num.(dev_id=%u)\n", dev_id);
560	        (void)pthread_mutex_unlock(&g_esched_init_mutex);
561	#ifdef CFG_FEATURE_EXTERNAL_CDEV
562	        esched_ex_dev_close(dev_id, fd);
563	#endif
564	        (void)esched_close(fd);
565	        return ret;
566	    }
567	
568	#ifdef CFG_FEATURE_EXTERNAL_CDEV
569	    sched_dev_fd[dev_id] = fd;
570	#else
571	    esched_init_all_fd(fd);
572	#endif
573	
574	    (void)pthread_mutex_unlock(&g_esched_init_mutex);
575	    return ret;
576	}
