583	
584	#ifdef CFG_FEATURE_EXTERNAL_CDEV
585	    esched_ex_dev_close(dev_id, sched_dev_fd[dev_id]);
586	#endif
587	    (void)esched_close(sched_dev_fd[dev_id]);
588	
589	#ifdef CFG_FEATURE_EXTERNAL_CDEV
590	    sched_dev_fd[dev_id] = SCHED_DEV_FD_CLOSED;
