596	int esched_dev_ioctl(unsigned int dev_id, unsigned int cmd, void *para)
597	{
598	    int ret;
599	    int fd;
600	
601	    while (1) {
602	        ret = esched_dev_init(dev_id);
603	        if (ret != 0) {
604	            return ret;
605	        }
606	
607	        fd = sched_dev_fd[dev_id];
608	        if (fd == 0) {
609	            continue;
610	        }
611	
612	        ret = esched_ioctl(fd, cmd, para);
613	        if (ret == DRV_ERROR_FILE_OPS) {
614	            esched_init_global_fork(dev_id, fd);
615	            continue;
616	        }
617	        if (ret != 0) {
618	            esched_share_log_read();
619	        }
620	
621	        break;
622	    }
623	
624	    return ret;
625	}
