653	static drvError_t esched_wait_event_comm(esched_thread_info *wait_info, int32_t timeout, struct event_info *event,
654	    esched_event_buffer *event_buffer)
655	{
656	    drvError_t ret;
657	    struct sched_ioctl_para_wait para;
658	    uint64_t wait_start_timestamp = esched_get_cur_cpu_timestamp();
659	    esched_thread_wait_info_head *wait_info_head = NULL;
660	
661	    wait_info_head = esched_get_thread_wait_info_list_head();
662	    if (wait_info_head == NULL) {
663	        esched_create_thread_wait_info_list_head();
664	    }
665	
666	    esched_finish_call_back(wait_info->dev_id, wait_info->gid, wait_info->tid);
667	
668	    para.input.dev_id = wait_info->dev_id;
669	    para.input.grp_id = wait_info->gid;
670	    para.input.thread_id = wait_info->tid;
671	    para.input.timeout = (timeout < 0) ? SCHED_WAIT_TIMEOUT_ALWAYS_WAIT : timeout;
672	    para.input.msg_len = event_buffer->msg_len;
673	    para.input.msg = event_buffer->msg;
674	
675	    do {
676	        ret = esched_dev_ioctl(wait_info->dev_id, SCHED_WAIT_EVENT_ID, &para);
677	    } while (ret == DRV_ERROR_WAIT_INTERRUPT);
678	
679	    if (ret != DRV_ERROR_NONE) {
680	        return ret;
681	    }
682	
683	    event->comm.pid = para.event.pid;
684	    event->comm.host_pid = para.event.host_pid;
685	    event->comm.grp_id = para.event.gid;
686	    event->comm.event_id = (EVENT_ID)para.event.event_id;
687	    event->comm.subevent_id = para.event.subevent_id;
688	    event->priv.msg_len = para.event.msg_len;
689	    event->comm.submit_timestamp = para.event.publish_user_timestamp;
690	    event->comm.sched_timestamp = para.event.subscribe_timestamp;
691	
692	    esched_save_wait_info(wait_info->dev_id, wait_info->tid, para);
693	
694	    esched_trace_record_call_back(wait_info->gid, &para.event, wait_start_timestamp);
695	
696	    return DRV_ERROR_NONE;
697	}
