730	static drvError_t esched_thread_swapout_common(unsigned int dev_id, unsigned int grp_id, unsigned int thread_id, int timeout)
731	{
732	    struct sched_ioctl_para_wait para = {0};
733	    drvError_t ret;
734	    unsigned int grp_id_ = grp_id;
735	    unsigned int thread_id_ = thread_id;
736	    GROUP_TYPE type;
737	
738	    if (esched_need_judge_thread_id()) {
739	        if (esched_get_cur_thread_id() == SCHED_INVALID_TID) {
740	            return DRV_ERROR_NONE;
741	        }
742	    }
743	
744	    if ((grp_id_ == SCHED_INVALID_GID) && (thread_id_ == SCHED_INVALID_TID)) {
745	        grp_id_ = esched_get_cur_group_id();
746	        thread_id_ = esched_get_cur_thread_id();
747	    }
748	
749	    para.input.dev_id = dev_id;
750	    para.input.grp_id = grp_id_;
751	    para.input.thread_id = thread_id_;
752	    para.input.timeout = timeout;
753	
754	    esched_finish_call_back(dev_id, grp_id_, thread_id_);
755	
756	    ret = esched_query_grp_type(dev_id, grp_id_, &type);
757	    if (ret != 0) {
758	        sched_err("Query grp type failed. (dev_id=%u; grp_id=%u; thread_id=%u)\n", dev_id, grp_id_, thread_id_);
759	        return DRV_ERROR_PARA_ERROR;
760	    }
761	
762	    /* non sched cpu not need swap out in kernel. */
763	    if (type == GRP_TYPE_BIND_CP_CPU) {
764	        esched_update_cur_thread_info(SCHED_INVALID_GID, SCHED_INVALID_TID);
765	        return DRV_ERROR_NONE;
766	    }
767	
768	    ret = esched_dev_ioctl(dev_id, SCHED_WAIT_EVENT_ID, &para);
769	    ret = (ret == DRV_ERROR_NO_EVENT) ? 0 : ret;
770	    if (ret == 0) {
771	        esched_update_cur_thread_info(SCHED_INVALID_GID, SCHED_INVALID_TID);
772	    }
773	
774	    return ret;
775	}
