799	drvError_t halEschedGetEvent(uint32_t devId, uint32_t grpId, uint32_t threadId,
800	    EVENT_ID eventId, struct event_info *event)
801	{
802	    drvError_t ret;
803	    struct sched_ioctl_para_get_event para;
804	
805	    if (event == NULL) {
806	        sched_err("The variable event is NULL. (devId=%u; grpId=%u; threadId=%u)\n", devId, grpId, threadId);
807	        return DRV_ERROR_PARA_ERROR;
808	    }
809	
810	    para.input.dev_id = devId;
811	    para.input.grp_id = grpId;
812	    para.input.thread_id = threadId;
813	    para.input.event_id = (uint32_t)eventId;
814	    para.input.msg_len = EVENT_MAX_MSG_LEN;
815	    para.input.msg = event->priv.msg;
816	
817	    ret = esched_dev_ioctl(devId, SCHED_GET_EXACT_EVENT_ID, &para);
818	    if (ret != 0) {
819	        return ret;
820	    }
821	
822	    event->comm.pid = para.event.pid;
