1331	        return DRV_ERROR_INVALID_VALUE;
1332	    }
1333	
1334	    for (i = 0; i < sched_cpu_num; i++) {
1335	        *mask |= (0x1ULL << (i + sched_cpu_start));
1336	    }
1337	
1338	    return 0;
1339	}
