1369	            sched_cpu_start += cpu_info.comcpu_num;
1370	        } else {
1371	            sched_cpu_num = cpu_info.aicpu_num + cpu_info.comcpu_num;
1372	        }
1373	    }
1374	
1375	    cpu_para.dev_id = dev_id;
1376	    esched_init_cpu_mask(&cpu_para.cpu_mask);
1377	    ret = esched_set_sched_cpu_mask(&cpu_para.cpu_mask.mask[0], sched_cpu_start, sched_cpu_num);
1378	    if (ret != DRV_ERROR_NONE) {
