        sched_err("The value of grpId or event_id is out of range. (grpId=%u; event_id=%u)\n",
            grpId, (unsigned int)eventId);
        return DRV_ERROR_SCHED_PARA_ERR;
    }

    esched_ack_func[grpId][eventId] = ackFunc;

