216	    }
217	    if (vf_work_ctx->vsq_work_ctx_list == NULL) {
218	        ts_agent_err("vsq_work_ctx is null, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, vsq_num=%u",
219	                     dev_id, vf_id, ts_id, vsq_id, vf_work_ctx->vsq_num);
220	        return -EINVAL;
221	    }
222	    vsq_work_ctx = &vf_work_ctx->vsq_work_ctx_list[wq_sq_id];
223	    vsq_work_ctx->vsq_base_info.dev_id = dev_id;
224	    vsq_work_ctx->vsq_base_info.vf_id = vf_id;
225	    vsq_work_ctx->vsq_base_info.vsq_id = vsq_id;
226	    vsq_work_ctx->vsq_base_info.ts_id = ts_id;
227	    vsq_work_ctx->vsq_base_info.vsq_type = vsq_type;
228	
229	    ret = vsq_top_proc(&vsq_work_ctx->vsq_base_info, cmd_num);
230	    if (ret != 0) {
231	        ts_agent_err("vsq top proc failed, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, cmd_num=%u",
232	                     dev_id, vf_id, ts_id, vsq_id, cmd_num);
233	    }
234	
235	    if (ka_task_queue_work(vsq_work_ctx->wq, &vsq_work_ctx->proc_work)) {
236	        ts_agent_debug("schedule work success, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u",
237	                       dev_id, vf_id, ts_id, vsq_id);
238	    } else {
239	        ts_agent_debug("task is in schedule already, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u",
240	                       dev_id, vf_id, ts_id, vsq_id);
241	    }
242	    return ret;
243	}
