74	STATIC int convert_maintenance_task(const vsq_base_info_t *vsq_base_info, ts_task_t *task)
75	{
76	    ts_maintenance_task_t *maintenance_task = &task->u.maintenance_task;
77	    int ret;
78	    uint16_t v_stream_id = task->streamID;
79	    uint16_t target_id = maintenance_task->targetID;
80	    uint16_t goal = maintenance_task->goal;
81	    if ((goal == MAINTENANCE_GOAL_STREAM) || (goal == MAINTENANCE_GOAL_STREAM_TASK_RECYCLE)) {
82	        ret = convert_stream_id(vsq_base_info, target_id, &maintenance_task->targetID);
83	        if (ret != 0) {
84	            ts_agent_err("convert maintenance target (stream)id failed. v_stream_id=%u, target_id=%u, ret=%d.",
85	                         v_stream_id, target_id, ret);
86	            maintenance_task->targetID = KA_U16_MAX;
87	        } else {
88	            maintenance_task->v_target_id = target_id;
89	            ts_agent_debug("convert v_stream_id=%u to event_id=%u. v_stream_id=%u.",
90	                target_id, maintenance_task->targetID, v_stream_id);
91	        }
92	    } else if (goal == MAINTENANCE_GOAL_EVENT) {
93	        ret = convert_event_id(vsq_base_info, target_id, &maintenance_task->targetID);
94	        if (ret != 0) {
95	            ts_agent_err("convert maintenance target (event)id failed. v_stream_id=%u, target_id=%u, ret=%d.",
96	                         v_stream_id, target_id, ret);
97	            maintenance_task->targetID = KA_U16_MAX;
98	        } else {
99	            maintenance_task->v_target_id = target_id;
100	            ts_agent_debug("convert v_event_id=%u to event_id=%u. v_stream_id=%u.",
101	                target_id, maintenance_task->targetID, v_stream_id);
102	        }
103	    } else {
104	        ret = 0;
105	        // do nothing
106	        ts_agent_debug("task goal=%u no need convert. v_stream_id=%u.", goal, v_stream_id);
107	    }
108	    return ret;
109	}
