408	static int convert_task(const vsq_base_info_t *vsq_base_info, ts_task_t *task)
409	{
410	    task_convert_custom_fn_t custom_fn = NULL;
411	    int ret;
412	    int custom_convert_ret;
413	    if (task->type >= TS_TASK_TYPE_RESERVED) {
414	        ts_agent_err("task type is invalid. task_type=%u, task_id=%u.",
415	                     task->type, task->taskID);
416	        return -EINVAL;
417	    }
418	    custom_fn = g_task_convert_fn[task->type];
419	    // no custom convert function is allowed.
420	    if (custom_fn == NULL) {
421	        ts_agent_err("task does not config convert function. task_type=%u, task_id=%u.",
422	                     task->type, task->taskID);
423	        custom_convert_ret = -EINVAL;
424	    } else {
425	        custom_convert_ret = custom_fn(vsq_base_info, task);
426	        if (custom_convert_ret != 0) {
427	            ts_agent_err("custom convert task failed. ret=%d, task_type=%u, task_id=%u.",
428	                         custom_convert_ret, task->type, task->taskID);
429	            // don't return, convert_task_basic must convert.
430	            task->task_info_flag |= TS_TASK_INVALID_FLAG; /* set invalid flag */
431	        }
432	    }
433	
434	    // convert_task_basic must after custom_convert, as custom convert may use streamId.
435	    ret = convert_task_basic(vsq_base_info, task);
436	    if (ret != 0) {
437	        ts_agent_err("convert task basic failed. ret=%d, task_type=%u, task_id=%u.",
438	                     ret, task->type, task->taskID);
439	        task->task_info_flag |= TS_TASK_INVALID_FLAG; /* set invalid flag */
440	        return ret;
441	    }
442	
443	    return custom_convert_ret;
444	}
445	
446	static int proc_task(const vsq_base_info_t *vsq_base_info, char *task_buf, size_t buf_len)
447	{
448	    ts_task_t *task = NULL;
449	    ts_host_func_sq_send_msg_t *callback_msg = NULL;
450	    int ret;
451	    u16 v_stream_id;
452	
453	    switch (vsq_base_info->vsq_type) {
454	        case NORMAL_VSQCQ_TYPE: {
455	            task = (ts_task_t *) task_buf;
456	            ret = convert_task(vsq_base_info, task);
457	            if (ret != 0) {
458	                ts_agent_err("convert task failed. ret=%d, dev_id=%u, vf_id=%u, ts_id=%u, "
459	                             "vsq_id=%u, stream_id=%u, task_type=%u, task_id=%u.",
460	                             ret, vsq_base_info->dev_id, vsq_base_info->vf_id, vsq_base_info->ts_id,
461	                             vsq_base_info->vsq_id, task->streamID, task->type, task->taskID);
462	                // can not break, as error task is need send to ts also,
463	                // if not send, may lost cq report and can't update vsq_head.
464	            }
465	            break;
466	        }
467	        case CALLBACK_VSQCQ_TYPE: {
468	            // will be need convert later
469	            callback_msg = (ts_host_func_sq_send_msg_t *) task_buf;
470	            v_stream_id = callback_msg->stream_id;
471	            ret = convert_stream_id(vsq_base_info, v_stream_id, &callback_msg->stream_id);
472	            if (ret != 0) {
473	                ts_agent_err("convert stream id failed. v_stream_id=%u, ret=%d.", v_stream_id, ret);
474	                callback_msg->stream_id = KA_U16_MAX;
475	            } else {
476	                ts_agent_debug("callback sq stream id is need convert now. dev_id=%u, vf_id=%u, ts_id=%u, "
477	                               "vsq_id=%u, stream_id=%u, task_id=%u, v_stream_id=%u.",
478	                               vsq_base_info->dev_id, vsq_base_info->vf_id, vsq_base_info->ts_id,
479	                               vsq_base_info->vsq_id, callback_msg->stream_id, callback_msg->task_id, v_stream_id);
480	            }
481	            break;
482	        }
483	        default: {
484	            ts_agent_err("unknown vsq type. dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, vsq_type=%d.",
485	                         vsq_base_info->dev_id, vsq_base_info->vf_id, vsq_base_info->ts_id,
486	                         vsq_base_info->vsq_id, vsq_base_info->vsq_type);
487	            ret = -EINVAL;
488	            break;
489	        }
490	    }
491	    return ret;
492	}
493	
494	static int proc_vsq_by_range(const vsq_base_info_t *vsq_base, u32 head, u32 tail)
495	{
496	    const char *vsq_base_addr = (const char *)vsq_base->vsq_base_addr;
497	    u32 vsq_slot_size = vsq_base->vsq_slot_size;
498	    char task_buf[TS_TASK_COMMAND_SIZE];
499	    int ret = 0;
500	    u32 copy_size;
501	    u32 deal_count = 0;
502	    u32 curr_head = head;
503	    struct hvtsdrv_vsq_slot_info sq_slot;
504	
505	    ts_agent_debug("proc vsq, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, head=%u, tail=%u.",
506	        vsq_base->dev_id, vsq_base->vf_id, vsq_base->ts_id, vsq_base->vsq_id, head, tail);
507	
508	    copy_size = (vsq_slot_size > TS_TASK_COMMAND_SIZE) ? TS_TASK_COMMAND_SIZE : vsq_slot_size;
509	
510	    sq_slot.vsq_id = vsq_base->vsq_id;
511	    sq_slot.vsq_slot_addr = task_buf;
512	    sq_slot.vsq_slot_size = TS_TASK_COMMAND_SIZE;
513	
514	    while (curr_head != tail) {
515	        // copy task from vsq
516	        errno_t cp_ret = memcpy_s(task_buf, TS_TASK_COMMAND_SIZE, vsq_base_addr + curr_head * vsq_slot_size, copy_size);
517	        if (cp_ret != EOK) {
518	            ts_agent_err("memcpy task from vsq failed. cp_ret=%d, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, "
519	                         "vsq_slot_addr=%pk, vsq_slot_size=%u, head=%u.", cp_ret, vsq_base->dev_id, vsq_base->vf_id,
520	                vsq_base->ts_id, sq_slot.vsq_id, vsq_base_addr, vsq_slot_size, head);
521	            ret = -EINVAL;
522	            break;
523	        }
524	        ret = proc_task(vsq_base, task_buf, TS_TASK_COMMAND_SIZE);
525	        if (ret != 0) {
526	            ts_agent_err("proc_task failed. ret=%d, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, vsq_type=%d.",
527	                ret, vsq_base->dev_id, vsq_base->vf_id, vsq_base->ts_id, vsq_base->vsq_id, vsq_base->vsq_type);
528	            // can not break, as error task is need send to ts also,
529	            // if not send, may lost cq report and can't update vsq_head.
530	        }
531	        ret = hal_kernel_hvtsdrv_sq_write(vsq_base->dev_id, vsq_base->vf_id, vsq_base->ts_id, &sq_slot);
532	        if (ret != 0) {
533	            ts_agent_err("Driver sq write failed. ret=%d, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, vsq_slot_addr=%pk,"
534	                         " vsq_slot_size=%u.", ret, vsq_base->dev_id, vsq_base->vf_id, vsq_base->ts_id, sq_slot.vsq_id,
535	                sq_slot.vsq_slot_addr, sq_slot.vsq_slot_size);
536	            break;
537	        }
538	        ++deal_count;
539	        ++curr_head;
540	        curr_head = curr_head % vsq_base->vsq_dep;
541	    }
542	    if (deal_count > 0) {
543	        hal_kernel_hvtsdrv_sq_irq_trigger(vsq_base->dev_id, vsq_base->vf_id, vsq_base->ts_id, vsq_base->vsq_id);
544	    }
545	    ts_agent_debug(
546	        "proc vsq finish, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, head=%u, curr_head=%u, tail=%u, deal_count=%u.",
547	        vsq_base->dev_id, vsq_base->vf_id, vsq_base->ts_id, vsq_base->vsq_id, head, curr_head, tail, deal_count);
548	    return ret;
549	}
550	
551	void proc_vsq(vsq_base_info_t *vsq_base_info)
552	{
553	    // retry once when proc end.
554	    int retry_times = 1;
555	    ts_agent_debug("proc vsq begin, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u.",
556	                   vsq_base_info->dev_id, vsq_base_info->vf_id, vsq_base_info->ts_id, vsq_base_info->vsq_id);
557	    do {
558	        u32 head;
559	        u32 tail;
560	        int ret = get_vsq_head_and_tail(vsq_base_info, &head, &tail);
561	        if (ret != 0) {
562	            break;
563	        }
564	        if (head == tail) {
565	            ts_agent_debug("head is same as tail, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u, head=%u.",
566	                           vsq_base_info->dev_id, vsq_base_info->vf_id, vsq_base_info->ts_id, vsq_base_info->vsq_id,
567	                           head);
568	            break;
569	        }
570	        ret = proc_vsq_by_range(vsq_base_info, head, tail);
571	        if (ret != 0) {
572	            break;
573	        }
574	        retry_times--;
575	    } while (retry_times >= 0);
576	    ts_agent_debug("proc vsq end, dev_id=%u, vf_id=%u, ts_id=%u, vsq_id=%u.",
577	                   vsq_base_info->dev_id, vsq_base_info->vf_id, vsq_base_info->ts_id, vsq_base_info->vsq_id);
578	}
579	
580	int vsq_top_proc(vsq_base_info_t *vsq_base_info, u32 cmd_num)
581	{
582	    return EOK;
583	}
