74	STATIC int32_t esched_init_thread_res(uint32_t dev_id, uint32_t gid, uint32_t event_id, uint32_t tid, struct sync_event_res *res)
75	{
76	    int32_t ret = 0;
77	    struct event_info back_event_info = {0};
78	    unsigned long long event_bitmap = (1UL << event_id);
79	
80	    ret = (int)halEschedSubscribeEvent(dev_id, gid, tid, event_bitmap);
81	    if (ret != 0) {
82	        sched_err("Failed to invoke the halEschedSubscribeEvent. (ret=%d)\n", ret);
83	        return ret;
84	    }
85	
86	    (void)halEschedWaitEvent(dev_id, gid, tid, 0, &back_event_info);
87	    res->res.gid = gid;
88	    res->res.tid = tid;
89	    res->res.event_id = event_id;
90	    res->res.subevent_id = 0;
91	    res->occupied_flag = false;
92	    (void)pthread_mutex_init(&res->res_lock, NULL);
93	
94	    return DRV_ERROR_NONE;
95	}
