105	STATIC int32_t esched_init_ccpu_grp_res(uint32_t dev_id, uint32_t gid, uint32_t event_type, uint32_t grp_index)
106	{
107	    uint32_t thread_idx, event_id, tid;
108	    int32_t ret = 0;
109	    struct sync_event_res *res = NULL;
110	
111	    thread_idx = grp_index * SCHED_MAX_SYNC_THREAD_NUM_PER_GRP;
112	    for (tid = 0; tid < SCHED_MAX_SYNC_THREAD_NUM_PER_GRP; tid++) {
113	        res = &ccpu_sync_res[dev_id][event_type][thread_idx];
114	        event_id = SCHED_SYNC_START_EVENT_ID + tid;
115	        ret = esched_init_thread_res(dev_id, gid, event_id, tid, res);
116	        if (ret != 0) {
117	            sched_err("Failed to init sync thread. (ret=%d; dev_id=%d; gid=%d;)\n", ret, dev_id, gid);
118	            return ret;
119	        }
120	        thread_idx ++;
121	    }
122	    return DRV_ERROR_NONE;
123	}
124	
125	static long esched_get_cpu(unsigned int *cpu, unsigned int *node)
126	{
127	    return syscall(SYS_getcpu, cpu, node, NULL);
128	}
129	
130	STATIC struct sync_event_res *esched_get_aicpu_res(uint32_t dev_id)
131	{
132	    uint32_t gid, event_id, cpu_id, node;
133	    int32_t ret = 0;
134	    struct sync_event_aicpu_res *sync_res = NULL;
135	
136	    if (esched_get_cpu(&cpu_id, &node) != 0) {
137	        sched_err("Failed to get cpu id. (dev_id=%u)\n", dev_id);
138	        return NULL;
139	    }
140	    if (cpu_id >= EVENT_RES_MAX_NUM) {
141	        sched_err("cpu id is invalid. (dev_id=%u; cpu_id=%u)\n", dev_id, cpu_id);
142	        return NULL;
143	    }
144	    
145	    (void)pthread_mutex_lock(&init_mutex);
146	    sync_res = &aicpu_sync_res[dev_id][cpu_id];
147	    if (sync_res->sync_init_status == INITED_STATUS) {
148	        goto out;
149	    }
150	
151	    gid = aicpu_sync_res_grp[dev_id];
152	    event_id = SCHED_SYNC_START_EVENT_ID + cpu_id;
153	    ret = esched_init_thread_res(dev_id, gid, event_id, cpu_id, &sync_res->thead_res);
154	    if (ret != 0) {
155	        sched_err("Failed to subscribe thread. (ret=%d)\n", ret);
156	        (void)pthread_mutex_unlock(&init_mutex);
157	        return NULL;
158	    }
159	    sync_res->sync_init_status = INITED_STATUS;
160	    sched_info("Init aicpu sync msg thread. (cpu_id=%u; gid=%u)\n", cpu_id, gid);
161	out:
162	    (void)pthread_mutex_unlock(&init_mutex);
163	    return &sync_res->thead_res;
164	}
