169	    struct sync_event_res *res = NULL;
170	    for (event_type = NORMAL_EVENT; event_type < COMM_EVENT_TYPE_MAX; event_type++) {
171	        for (tid = 0; tid < EVENT_RES_MAX_NUM; tid++) {
172	            res = &ccpu_sync_res[dev_id][event_type][tid];
173	            res->occupied_flag = true;
174	        }
175	    }
176	
177	    for (cpuid = 0; cpuid < EVENT_RES_MAX_NUM; cpuid++) {
178	        res = &aicpu_sync_res[dev_id][cpuid].thead_res;
179	        res->occupied_flag = true;
180	    }
181	
182	    for (cpuid = 0; cpuid < DRV_MSG_EVENT_RES_MAX_NUM; cpuid++) {
183	        res = &drv_sync_res[dev_id][cpuid];
184	        res->occupied_flag = true;
185	    }
186	
187	    aicpu_sync_res_grp[dev_id] = 0;
188	}
