193	
194	    (void)pthread_mutex_lock(&init_mutex);
195	    sync_init_status[dev_id] = UNINITED_STATUS;
196	    for (i = 0; i < EVENT_RES_MAX_NUM; i++) {
197	        aicpu_sync_res[dev_id][i].sync_init_status = UNINITED_STATUS;
198	    }
199	    aicpu_sync_res_grp[dev_id] = 0;
200	    (void)pthread_mutex_unlock(&init_mutex);
