207	    uint32_t gid, curr_grp_index, i, event_type, cur_grp_num;
208	    struct esched_grp_para grp_para = {0};
209	    int32_t grp_num_per_event_type[COMM_EVENT_TYPE_MAX] = {4, 4, 4, 4};
210	
211	    /* support gid_index(0-15) and event_id(28-43) used for sync event res */
212	    for (event_type = 0; event_type < COMM_EVENT_TYPE_MAX; event_type++) {
213	        cur_grp_num = (uint32_t)grp_num_per_event_type[event_type];
214	        if ((cur_grp_num + inited_num) > SCHED_MAX_SYNC_GRP_NUM) {
215	            sched_err("sync group config error. (grp_inited_num=%u; event_type=%u)\n", inited_num, event_type);
216	            return DRV_ERROR_PARA_ERROR;
217	        }
218	        for (i = 0; i < cur_grp_num; i++) {
219	            curr_grp_index = i + inited_num;
220	            esched_grp_para_cfg(&grp_para, curr_grp_index);
221	            ret = (int)halEschedCreateGrpEx(dev_id, &grp_para, &gid);
222	            if (ret != 0) {
223	                sched_err("Failed to create group. (grp_index=%u; ret=%d)\n", curr_grp_index, ret);
224	                return ret;
225	            }
226	            ret = esched_init_ccpu_grp_res(dev_id, gid, event_type, i);
227	            if (ret != 0) {
228	                sched_err("Failed to init sync group. (grp_index=%u; ret=%d)\n", curr_grp_index, ret);
229	                return ret;
230	            }
231	        }
232	        inited_num += cur_grp_num;
233	    }
234	    return ret;
235	}
