237	STATIC int32_t esched_aicpu_res_init(uint32_t dev_id)
238	{
239	    int32_t ret, len;
240	    uint32_t gid;
241	    struct esched_grp_para grp_para = {0};
242	
243	    grp_para.type = GRP_TYPE_BIND_DP_CPU;
244	    grp_para.threadNum = EVENT_RES_MAX_NUM;
245	    len = snprintf_s(grp_para.grp_name, EVENT_MAX_GRP_NAME_LEN, EVENT_MAX_GRP_NAME_LEN - 1, "%s", "ESCHED_GRP_AI");
246	    if (len <= 0) {
247	        sched_err("Failed to init grp_name. (dev_id=%d)\n", dev_id);
