261	STATIC int32_t esched_drv_res_init(uint32_t dev_id)
262	{
263	    drvError_t ret;
264	    int32_t len;
265	    uint32_t gid, tid;
266	    struct esched_grp_para grp_para = {0};
267	    struct sync_event_res *res = NULL;
268	
269	    grp_para.type = GRP_TYPE_BIND_CP_CPU;
270	    grp_para.threadNum = DRV_MSG_EVENT_RES_MAX_NUM;
271	    len = snprintf_s(grp_para.grp_name, EVENT_MAX_GRP_NAME_LEN, EVENT_MAX_GRP_NAME_LEN - 1, "%s", "DRV_ESCHED_GRP");
272	    if (len <= 0) {
273	        sched_err("Failed to init grp_name. (dev_id=%d)\n", dev_id);
274	        return DRV_ERROR_PARA_ERROR;
275	    }
276	
277	    ret = halEschedCreateGrpEx(dev_id, &grp_para, &gid);
278	    if (ret != DRV_ERROR_NONE) {
279	        sched_err("Call hal_esched_create_grp failed. (dev_id=%u, ret=%d)\n", dev_id, (int)ret);
280	        return ret;
281	    }
282	
283	    for (tid = 0; tid < DRV_MSG_EVENT_RES_MAX_NUM; tid++) {
284	        res = &drv_sync_res[dev_id][tid];
285	        ret = esched_init_thread_res(dev_id, gid, EVENT_DRV_MSG_EX, tid, res);
286	        if (ret != 0) {
287	            sched_err("Failed to init sync thread. (ret=%d; dev_id=%d; gid=%d;)\n", ret, dev_id, gid);
288	            return ret;
289	        }
290	    }
291	    sched_info("Init drv inner sync res group success. (dev_id=%u, gid=%u)\n", dev_id, gid);
292	
293	    return DRV_ERROR_NONE;
294	}
