296	STATIC int32_t esched_res_init(uint32_t dev_id)
297	{
298	    int32_t ret = 0;
299	
300	    (void)pthread_mutex_lock(&init_mutex);
301	    if (sync_init_status[dev_id] == INITED_STATUS) {
302	        goto out;
303	    }
304	    esched_sync_res_invalid(dev_id);
305	
306	    ret = (int)halEschedAttachDevice(dev_id);
307	    if ((ret != 0) && (ret != DRV_ERROR_PROCESS_REPEAT_ADD)) {
308	        sched_err("Failed to attach device. (ret=%d)\n", ret);
309	        goto out;
310	    }
311	
312	    ret = esched_ccpu_res_init(dev_id);
313	    if (ret != 0) {
314	        sched_err("Failed to init comm res. (ret=%d)\n", ret);
315	        goto out;
316	    }
317	
318	    ret = esched_aicpu_res_init(dev_id);
319	    if (ret != 0) {
320	        sched_err("Failed to init aicpu res. (ret=%d)\n", ret);
321	        goto out;
322	    }
323	
324	    ret = esched_drv_res_init(dev_id);
325	    if (ret != 0) {
326	        sched_err("Failed to init drv res. (ret=%d)\n", ret);
327	        goto out;
328	    }
329	    sync_init_status[dev_id] = INITED_STATUS;
330	    sched_info("Init sync res group success. (dev_id=%u)\n", dev_id);
331	out:
332	    (void)pthread_mutex_unlock(&init_mutex);
333	    return ret;
334	}
