336	STATIC struct sync_event_res *esched_get_event_res_pool(uint32_t dev_id, int32_t event_type, int32_t *max_thread)
337	{
338	    int32_t thread_num;
339	    struct sync_event_res *res = NULL;
340	
341	    switch (event_type) {
342	        case DRV_INNER_EVENT:
343	            thread_num = DRV_MSG_EVENT_RES_MAX_NUM;
344	            res = &drv_sync_res[dev_id][0];
345	            break;
346	        case QUEUE_ACPU_EVENT:
347	            thread_num = 1;
348	            res = esched_get_aicpu_res(dev_id);
349	            break;
350	        default :
351	            thread_num = EVENT_RES_MAX_NUM;
352	            res = &ccpu_sync_res[dev_id][event_type][0];
353	            break;
354	    }
355	    *max_thread = thread_num;
356	    return res;
357	}
358	
359	STATIC int32_t esched_find_idle_res(struct sync_event_res *res, int32_t max_thread, struct event_res *e_res)
360	{
361	#ifndef EMU_VCAST_ST
362	    int32_t i;
363	
364	    for (i = 0; i < max_thread; i++) {
365	        (void)pthread_mutex_lock(&res[i].res_lock);
366	        if (res[i].occupied_flag == false) {
367	            res[i].res.subevent_id++;
368	            res[i].res.subevent_id = (res[i].res.subevent_id >= SCHED_SYNC_MAX_SUB_EVENT_ID) ? 0 : res[i].res.subevent_id;
369	            *e_res = res[i].res;
370	            res[i].occupied_flag = true;
371	            (void)pthread_mutex_unlock(&res[i].res_lock);
372	            return 0;
373	        }
374	        (void)pthread_mutex_unlock(&res[i].res_lock);
375	    }
376	    return (int32_t)DRV_ERROR_NO_EVENT_RESOURCES;
377	#else
378	    return 0;
379	#endif
380	}
381	
382	int32_t esched_alloc_event_res(uint32_t dev_id, int32_t event_type, struct event_res *e_res)
383	{
384	    int32_t max_thread, ret;
385	    struct sync_event_res *res = NULL;
386	
387	    if ((esched_device_check(dev_id) != 0) || (event_type >= EVENT_TYPE_BUTT)) {
388	        sched_err("Invalid para. (dev_id=%u; event_type=%d)\n", dev_id, event_type);
389	        return DRV_ERROR_PARA_ERROR;
390	    }
391	
392	    ret = esched_res_init(dev_id);
393	    if (ret != 0) {
394	        sched_err("esched_res_init failed. (ret=%d; dev_id=%u; event_type=%d)\n", ret, dev_id, event_type);
395	        return ret;
396	    }
397	
398	    res = esched_get_event_res_pool(dev_id, event_type, &max_thread);
399	    if (res == NULL) {
400	        sched_err("sync res alloc failed. (ret=%d; dev_id=%u; event_type=%d)\n", ret, dev_id, event_type);
401	        return ret;
402	    }
403	
404	    return esched_find_idle_res(res, max_thread, e_res);
405	}
