407	STATIC void esched_ccpu_res_free(uint32_t devId, int32_t event_type, const struct event_res *e_res)
408	{
409	    struct sync_event_res *res = NULL;
410	    int32_t i;
411	
412	    for (i = 0; i < (int32_t)EVENT_RES_MAX_NUM; i++) {
413	        res = &ccpu_sync_res[devId][event_type][i];
414	        (void)pthread_mutex_lock(&res->res_lock);
415	        if ((e_res->gid == res->res.gid) && (e_res->tid == res->res.tid) && (e_res->event_id == res->res.event_id)) {
416	            res->occupied_flag = false;
417	            (void)pthread_mutex_unlock(&res->res_lock);
418	            return;
419	        }
420	        (void)pthread_mutex_unlock(&res->res_lock);
421	    }
422	}
423	
424	STATIC void esched_aicpu_res_free(uint32_t dev_id)
425	{
426	    struct sync_event_res *res = esched_get_aicpu_res(dev_id);
427	
428	    if (res == NULL) {
429	        sched_err("get res failed. (dev_id=%u)\n", dev_id);
430	        return;
431	    }
432	
433	    (void)pthread_mutex_lock(&res->res_lock);
434	    if (res->occupied_flag == false) {
435	        (void)pthread_mutex_unlock(&res->res_lock);
436	        sched_info("aicpu sync res exception. (dev_id=%u; tid=%d)\n", dev_id, res->res.tid);
437	        return;
438	    }
439	    res->occupied_flag = false;
440	    (void)pthread_mutex_unlock(&res->res_lock);
441	}
442	
443	STATIC void esched_drv_res_free(uint32_t dev_id, const struct event_res *e_res)
444	{
445	    struct sync_event_res *res = NULL;
446	    uint32_t tid = e_res->tid;
447	
448	    if (tid >= DRV_MSG_EVENT_RES_MAX_NUM) {
449	        sched_err("Invalid para. (dev_id=%u; tid=%d)\n", dev_id, tid);
450	        return;
451	    }
452	
453	    res = &drv_sync_res[dev_id][tid];
454	    (void)pthread_mutex_lock(&res->res_lock);
455	    if (res->occupied_flag == false) {
456	        (void)pthread_mutex_unlock(&res->res_lock);
457	        sched_err("sync res exception. (dev_id=%u; tid=%d)\n", dev_id, tid);
458	        return;
459	    }
460	    res->occupied_flag = false;
461	    (void)pthread_mutex_unlock(&res->res_lock);
462	}
