465	void esched_free_event_res(uint32_t dev_id, int32_t event_type, const struct event_res *e_res)
466	{
467	    if ((esched_device_check(dev_id) != 0) || (event_type >= EVENT_TYPE_BUTT)) {
468	        sched_err("Invalid para. (dev_id=%u; event_type=%d)\n", dev_id, event_type);
469	        return;
470	    }
471	
472	    switch (event_type) {
473	        case DRV_INNER_EVENT:
474	            esched_drv_res_free(dev_id, e_res);
475	            break;
476	        case QUEUE_ACPU_EVENT:
477	            esched_aicpu_res_free(dev_id);
478	            break;
479	        default :
480	            esched_ccpu_res_free(dev_id, event_type, e_res);
481	            break;
482	    }
483	    return;
484	}
