486	void esched_fill_sync_msg(struct event_summary *event, const struct event_res *res)
487	{
488	    unsigned int dst_engine;
489	
490	    (void)dst_engine;
491	    dst_engine = event->dst_engine;
492	    ((struct event_sync_msg *)event->msg)->pid = (uint32_t)GETPID() & 0x3FFFFF;
