497	        ((struct event_sync_msg *)event->msg)->pid = (uint32_t)drvDeviceGetBareTgid() & 0x3FFFFF;
498	    }
499	#else
500	    if ((dst_engine == ACPU_HOST) || (dst_engine == CCPU_HOST)) {
501	        ((struct event_sync_msg *)event->msg)->pid = drvDeviceGetBareTgid();
502	    }
503	#endif
504	#endif
505	
506	#ifdef CFG_ENV_HOST
507	    ((struct event_sync_msg *)event->msg)->dst_engine = CCPU_HOST;
508	#else
509	#ifdef CFG_SOC_PLATFORM_HELPER
510	    ((struct event_sync_msg *)event->msg)->dst_engine = CCPU_HOST;
511	#else
512	    ((struct event_sync_msg *)event->msg)->dst_engine = CCPU_DEVICE;
513	#endif
514	#endif
515	    ((struct event_sync_msg *)event->msg)->gid = (uint32_t)res->gid & 0x3F;
516	    ((struct event_sync_msg *)event->msg)->event_id = (uint32_t)res->event_id & 0x3F;
517	    ((struct event_sync_msg *)event->msg)->subevent_id = res->subevent_id;
