541	
542	#if defined(CFG_ENV_HOST) && defined(CFG_SOC_PLATFORM_CLOUD_V4)
543	#define SVM_SYNC_EVENT_SINGLE_WAIT_TIME (10 * 1000)  /* 10s */
544	#endif
545	static int esched_wait_sync_event(uint32_t dev_id, struct sync_event_wait_info *wait_info, struct event_info *back_event_info)
546	{
547	#if defined(CFG_ENV_HOST) && defined(CFG_SOC_PLATFORM_CLOUD_V4)
548	    int32_t ret;
549	    int32_t timeout = wait_info->timeout;
550	    int32_t wait_time;
551	    int32_t query_ret;
552	
553	    if ((wait_info->subevent_id >= DRV_SUBEVENT_SVM_DEV_OPEN_MSG) && (wait_info->subevent_id < DRV_SUBEVENT_HDC_CREATE_LINK_MSG)) {
554	        if (timeout > SVM_SYNC_EVENT_SINGLE_WAIT_TIME) {
555	            while (timeout > 0) {
556	                wait_time = timeout > SVM_SYNC_EVENT_SINGLE_WAIT_TIME ? SVM_SYNC_EVENT_SINGLE_WAIT_TIME : timeout;
557	                timeout = timeout - wait_time;
558	                ret = (int)esched_wait_event_ex(dev_id, wait_info->grp_id, wait_info->thread_id, wait_time, back_event_info);
559	                if (ret != DRV_ERROR_WAIT_TIMEOUT) {
560	                    return ret;
561	                }
562	                query_ret = halQueryMasterPidByDeviceSlave(dev_id, wait_info->pid, NULL, NULL);
563	                if (query_ret != 0) {
564	                    sched_run_info("Query device pid not success. (devid=%d, pid=%d; ret=%d)\n", dev_id, wait_info->pid, query_ret);
565	                    return query_ret;
566	                }
567	            }
568	        } else {
569	            ret = (int)esched_wait_event_ex(dev_id, wait_info->grp_id, wait_info->thread_id, timeout, back_event_info);
570	        }
571	    } else {
572	        ret = (int)esched_wait_event_ex(dev_id, wait_info->grp_id, wait_info->thread_id, timeout, back_event_info);
573	    }
574	    return ret;
575	#else
576	    return (int)esched_wait_event_ex(dev_id, wait_info->grp_id, wait_info->thread_id, wait_info->timeout, back_event_info);
577	#endif
578	}
579	
580	static void esched_fill_wait_info(struct sync_event_wait_info *wait_info, struct event_summary *event,
581	    struct event_res *res, int32_t timeout)
582	{
583	    wait_info->grp_id = res->gid;
584	    wait_info->thread_id = res->tid;
585	    wait_info->pid = event->pid;
586	    wait_info->event_id = event->event_id;
587	    wait_info->subevent_id = event->subevent_id;
588	    wait_info->timeout = timeout;
589	    return;
590	}
591	
592	drvError_t halEschedSubmitEventSync(uint32_t devId, struct event_summary *event, int32_t timeout,
593	    struct event_reply *reply)
594	{
595	    int wait_succ_cnt = 0;
596	    int32_t ret, event_type;
597	    struct event_res res;
598	    struct event_info back_event_info;
599	    esched_event_buffer *event_buffer = (esched_event_buffer *)back_event_info.priv.msg;
600	    unsigned long long timestamp = esched_get_cur_cpu_timestamp();
601	    struct sync_event_wait_info wait_info = {0};
602	
603	    if (event == NULL) {
604	        sched_err("The variable event is NULL.\n");
605	        report_arg_null_pointer(__FUNCTION__, "event");
606	        return DRV_ERROR_PARA_ERROR;
607	    }
608	    if (reply == NULL) {
609	        sched_err("The variable reply is NULL.\n");
610	        report_arg_null_pointer(__FUNCTION__, "reply");
611	        return DRV_ERROR_PARA_ERROR;
612	    }
613	    if (event->msg == NULL) {
614	        sched_err("The event->msg is NULL.\n");
615	        report_arg_null_pointer(__FUNCTION__, "event->msg");
616	        return DRV_ERROR_PARA_ERROR;
617	    }
618	    if (event->msg_len < sizeof(struct event_sync_msg)) {
619	        sched_err("event->msg_len is invalid.(event->msg_len=%u)\n", event->msg_len);
620	        return DRV_ERROR_PARA_ERROR;
621	    }
622	
623	    event_type = (event->event_id == EVENT_DRV_MSG_EX) ? DRV_INNER_EVENT : NORMAL_EVENT;
624	    ret = esched_alloc_event_res(devId, event_type, &res);
625	    if (ret != 0) {
626	        sched_err("Failed to invoke the Esched_sync_init. (ret=%d)\n", ret);
627	        return ret;
628	    }
629	
630	    if (event_type == DRV_INNER_EVENT) {
631	        res.subevent_id = (uint32_t)event->subevent_id & 0xFFF;
632	    }
633	    esched_fill_sync_msg(event, &res);
634	    ret = (int)halEschedSubmitEvent(devId, event);
635	    if (ret != 0) {
636	        /* flowgw maybe not ready, client will retry. */
637	        sched_warn("Unable to invoke the halEschedSubmitEvent. (devId=%u, event_id=%u; ret=%d)\n",
638	            devId, event->event_id, ret);
639	        esched_free_event_res(devId, event_type, &res);
640	        return ret;
641	    }
642	
643	    event_buffer->msg = reply->buf;
644	    event_buffer->msg_len = reply->buf_len;
645	
646	    do {
647	        esched_fill_wait_info(&wait_info, event, &res, timeout);
648	        ret = esched_wait_sync_event(devId, &wait_info, &back_event_info);
649	        if (ret != 0) {
650	            if ((ret == DRV_ERROR_WAIT_TIMEOUT) || (esched_is_svm_alloc_event(event->event_id, event->subevent_id))) {
651	                sched_run_info("Sync event not success. (ret=%d; dst_pid=%d; event_id=%u; subevent_id=%u; "
652	                    "sync_gid=%u; sync_event_id=%u; sync_subevent_id=%u; sync_tid=%u; timeout=%dms; current_tick=%llu)\n",
653	                    ret, event->pid, event->event_id, event->subevent_id, res.gid, res.event_id, res.subevent_id, res.tid, timeout, timestamp);
654	            } else {
655	                sched_err("Sync event failed. (ret=%d; dst_pid=%d; event_id=%u; subevent_id=%u; "
656	                    "sync_gid=%u; sync_event_id=%u; sync_subevent_id=%u; sync_tid=%u; timeout=%dms; current_tick=%llu)\n",
657	                    ret, event->pid, event->event_id, event->subevent_id, res.gid, res.event_id, res.subevent_id, res.tid, timeout, timestamp);
658	            }
659	            if (ret == DRV_ERROR_WAIT_TIMEOUT) {
660	                esched_query_sync_msg_trace(devId, event, res.gid, res.tid);
661	            }
662	            esched_free_event_res(devId, event_type, &res);
663	            return ret;
664	        }
665	
666	        wait_succ_cnt++;
667	        if ((back_event_info.comm.submit_timestamp >= timestamp) &&
668	            (back_event_info.comm.subevent_id == res.subevent_id)) {
669	            break;
670	        }
671	
672	        sched_run_info("Successfully waited for an event but the condition was not met. (devid=%u; gid=%u; "
673	            "tid=%u; cnt=%d; check_time=%llu; back_time=%llu; check_subevent=%u; back_subevent=%u)\n",
674	            devId, res.gid, res.tid, wait_succ_cnt, timestamp, back_event_info.comm.submit_timestamp,
675	            res.subevent_id, back_event_info.comm.subevent_id);
676	    } while (1);
677	
678	    esched_free_event_res(devId, event_type, &res);
679	
680	    reply->reply_len = back_event_info.priv.msg_len;
681	
682	    return 0;
683	}
