157	int drv_event_proc(unsigned int dev_id, struct event_info *event, esched_event_buffer *msg_buffer,
158	    struct event_proc_result_buffer *rsp_buffer)
159	{
160	    struct event_sync_msg *msg_head = NULL;
161	    struct event_summary back_event = {0};
162	    struct drv_event_proc_rsp rsp = {0};
163	    drvError_t ret;
164	    unsigned int dst_dev_id = SCHED_INVALID_DEVID;
165	    unsigned int tid = SCHED_INVALID_TID;
166	
167	    ret = drv_check_event(event);
168	    if (ret != DRV_ERROR_NONE) {
169	        DRV_EVENT_LOG_ERR("Check_event failed, ret=%d.\n", ret);
170	        return ret;
171	    }
172	    DRV_EVENT_LOG_DBG("Event_proc start. (devid=%u)\n", dev_id);
173	
174	    rsp.rsp_data_buf = (void *)DRV_EVENT_REPLY_BUFFER_DATA_PTR(rsp_buffer->buffer);
175	    rsp.rsp_data_buf_len = (int)(rsp_buffer->buffer_len - (int)sizeof(int));
176	    rsp.need_rsp = true;
177	
178	    ret = drv_event_proc_dispatch(dev_id, event, msg_buffer, &rsp);
179	    if (ret != DRV_ERROR_NONE) {
180	        DRV_EVENT_LOG_DBG("Event_proc not success, ret=%d, subevent_id=%d.\n", ret, event->comm.subevent_id);
181	    }
182	
183	    if (rsp.real_rsp_data_len > rsp.rsp_data_buf_len) {
184	        DRV_EVENT_LOG_ERR("Rsp_len beyond. (rsp_len=%d; max=%d)\n", rsp.real_rsp_data_len,
185	            rsp_buffer->buffer_len - (int)sizeof(int));
186	#ifndef EMU_ST
187	        return DRV_ERROR_INNER_ERR;
188	#endif
189	    }
190	
191	    /* not need submit */
192	    if (rsp.need_rsp == false) {
193	        return DRV_ERROR_NONE;
194	    }
195	
196	    msg_head = (struct event_sync_msg *)msg_buffer->msg;
197	    drv_update_dst_devid(msg_head, &dst_dev_id, &tid);
198	    DRV_EVENT_REPLY_BUFFER_RET(rsp_buffer->buffer) = ret;
199	    back_event.dst_engine = msg_head->dst_engine;
200	    back_event.policy = ONLY;
201	    back_event.pid = msg_head->pid;
202	    back_event.grp_id = msg_head->gid;
203	    back_event.event_id = msg_head->event_id;
204	    back_event.subevent_id = msg_head->subevent_id;
205	    back_event.msg_len = (uint32_t)(rsp.real_rsp_data_len + (int)sizeof(ret));
206	    back_event.msg = rsp_buffer->buffer;
207	    back_event.tid = (msg_head->event_id == EVENT_DRV_MSG_EX) ? msg_head->tid : tid;
208	    ret = halEschedSubmitEventEx(dev_id, dst_dev_id, &back_event);
209	    if (ret != 0) {
210	#ifndef EMU_ST
211	        DRV_EVENT_LOG_RUN_INFO("halEschedSubmitEvent, ret=%d.\n", ret);
212	#endif
213	    }
214	
215	    DRV_EVENT_LOG_DBG("Event_proc end. (proc_name=%s; dst_dev_id=%u; pid=%u; dst_engine=%u; event_id=%u; gid=%u; subevent_id=%u)\n",
216	        g_drv_event_proc[event->comm.subevent_id].proc_name, dst_dev_id,
217	        msg_head->pid, msg_head->dst_engine, msg_head->event_id, msg_head->gid, msg_head->subevent_id);
218	
219	    return ret;
