239	static int drv_event_query_grid(unsigned int dev_id, unsigned int *grp_id)
240	{
241	    struct esched_query_gid_output gid_out = {0};
242	    struct esched_query_gid_input gid_in = {0};
243	    struct esched_output_info out_put = {0};
244	    struct esched_input_info in_put = {0};
245	    drvError_t ret;
