261	static void *drv_event_thread_proc(void *data)
262	{
263	    unsigned int dev_id = (unsigned int)(uintptr_t)data;
264	    struct event_info event;
265	    esched_event_buffer *event_buffer = (esched_event_buffer *)event.priv.msg;
266	    struct event_proc_result_buffer rsp_buffer = {0};
267	    unsigned int grp_id;
268	    int ret;
269	
270	    (void)prctl(PR_SET_NAME, "drv_event_proc");
271	    ret = drv_event_query_grid(dev_id, &grp_id);
272	    if (ret != DRV_ERROR_NONE) {
273	        DRV_EVENT_LOG_ERR("Get gid failed. (ret=%d; dev_id=%u, tgid=%d)\n", ret, dev_id, getpid());
274	        return NULL;
275	    }
276	
277	    event_buffer->msg = (char *)malloc(sizeof(char) * DRV_PROC_WAIT_BUFFER_LEN);
278	    if (event_buffer->msg == NULL) {
279	        DRV_EVENT_LOG_ERR("Malloc wait buffer failed. (dev_id=%u, tgid=%d)\n", dev_id, getpid());
280	        return NULL;
281	    }
282	    event_buffer->msg_len = DRV_PROC_WAIT_BUFFER_LEN;
283	
284	    rsp_buffer.buffer = (char *)malloc(sizeof(char) * EVENT_PROC_RESULT_BUFFER_LEN);
285	    if (rsp_buffer.buffer == NULL) {
286	        free(event_buffer->msg);
287	        DRV_EVENT_LOG_ERR("Malloc rep buffer failed. (dev_id=%u, tgid=%d)\n", dev_id, getpid());
288	        return NULL;
289	    }
290	    rsp_buffer.buffer_len = sizeof(char) * EVENT_PROC_RESULT_BUFFER_LEN;
291	
292	    while (1) {
293	        ret = esched_wait_event_ex(dev_id, grp_id, 0, 10000, &event); /* timeout 10000 ms */
294	        if (ret == DRV_ERROR_NONE) {
295	            DRV_EVENT_LOG_DBG("Wait event. (dev_id=%u; event_id=%u; subevent_id=%u)\n",
296	                dev_id, event.comm.event_id, event.comm.subevent_id);
297	            if ((event.comm.event_id == EVENT_DRV_MSG) || (event.comm.event_id == EVENT_DRV_MSG_EX)) {
298	                (void)drv_event_proc(dev_id, &event, event_buffer, &rsp_buffer);
299	            }
300	        } else if ((ret != DRV_ERROR_SCHED_WAIT_TIMEOUT) && (ret != DRV_ERROR_NO_EVENT)) {
301	            break;
302	        }
303	    }
304	
305	    free(rsp_buffer.buffer);
306	    free(event_buffer->msg);
307	
308	    return NULL;
309	}
