311	static int drv_event_create_task_with_detach(unsigned int dev_id)
312	{
313	    pthread_t event_thread;
314	    pthread_attr_t attr;
315	    int ret;
316	
317	    (void)pthread_attr_init(&attr);
318	    (void)pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
319	
320	    ret = pthread_create(&event_thread, &attr, drv_event_thread_proc, (void *)(unsigned long)dev_id);
321	    (void)pthread_attr_destroy(&attr);
322	    if (ret != 0) {
323	        return DRV_ERROR_INNER_ERR;
324	    }
325	
326	    return DRV_ERROR_NONE;
327	}
328	
329	drvError_t halDrvEventThreadInit(unsigned int devId)
330	{
331	    struct event_info event = {0};
332	    struct esched_grp_para grp_para;
333	    unsigned long event_bitmap = ((0x1 << EVENT_DRV_MSG) | (0x1 << EVENT_DRV_MSG_EX));
334	    unsigned int grp_id;
335	    int ret;
336	
337	    /* process attach device only need once */
338	    ret = halEschedAttachDevice(devId);
339	    if (ret != DRV_ERROR_NONE) {
340	        if (ret != DRV_ERROR_PROCESS_REPEAT_ADD) {
341	            DRV_EVENT_LOG_ERR("Call halEschedAttachDevice failed. (devId=%u, ret=%d)\n", devId, ret);
342	            return ret;
343	        }
344	    }
345	#ifndef EMU_ST
346	    (void)pthread_mutex_lock(&g_drv_thread_lock);
347	    ret = drv_event_query_grid(devId, &grp_id);
348	    if (ret == DRV_ERROR_NONE) {
349	        (void)pthread_mutex_unlock(&g_drv_thread_lock);
350	        return DRV_ERROR_NONE;
351	    }
352	
353	    /* process attach device only need once */
354	    grp_para.type = GRP_TYPE_BIND_CP_CPU;
355	    grp_para.threadNum = 1;
356	    grp_para.rsv[0] = 0; // rsv word 0
357	    grp_para.rsv[1] = 0; // rsv word 1
358	    grp_para.rsv[2] = 0; // rsv word 2
359	    (void)strcpy_s(grp_para.grp_name, EVENT_MAX_GRP_NAME_LEN, EVENT_DRV_MSG_GRP_NAME);
360	
361	    ret = halEschedCreateGrpEx(devId, &grp_para, &grp_id);
362	    if (ret != DRV_ERROR_NONE) {
363	        (void)pthread_mutex_unlock(&g_drv_thread_lock);
364	        (void)halEschedDettachDevice(devId);
365	        DRV_EVENT_LOG_ERR("Call halEschedCreateGrpEx failed. (devId=%u, ret=%d)\n", devId, ret);
366	        return ret;
367	    }
368	    (void)pthread_mutex_unlock(&g_drv_thread_lock);
369	#endif
370	    ret = halEschedSubscribeEvent(devId, grp_id, 0, event_bitmap);
371	    if (ret != DRV_ERROR_NONE) {
372	        (void)halEschedDettachDevice(devId);
373	        DRV_EVENT_LOG_ERR("Call halEschedSubscribeEvent failed. (devId=%u; ret=%d)\n", devId, ret);
374	        return ret;
375	    }
376	
377	    (void)halEschedWaitEvent(devId, grp_id, 0, 0, &event); /* wait timeout 0s to register subscriber */
378	    ret = drv_event_create_task_with_detach(devId);
379	    if (ret != 0) {
380	        (void)halEschedDettachDevice(devId);
381	        DRV_EVENT_LOG_ERR("Call drv_event_create_task_with_detach failed. (devId=%u; ret=%d)\n", devId, ret);
382	        return ret;
383	    }
384	
385	    return DRV_ERROR_NONE;
386	}
387	
388	drvError_t halDrvEventThreadUninit(unsigned int devId)
389	{
390	    return halEschedDettachDevice(devId);
391	}
