    CALLBACK_VSQCQ_TYPE
};

struct hvtsdrv_vsq_info {
    const void *vsq_base_addr; // vsq base addr alloced by drv
    u32 vsq_dep;               // 1024
    u32 vsq_slot_size;         // 64
};

struct hvtsdrv_vsq_head_tail {
    u32 head;
    u32 tail;
};

