    u32 dev_id;
    u32 fid;
    u32 ts_id;
    u32 disable_thread; // 0:with thread, 1:disable thread
};

struct hvtsdrv_tsagent_ops {
    int (*tsagent_vf_create)(u32 devid, u32 fid);
